H.background();
const k = 8.99e9;
const q = P.q; // microcoulombs, can be negative
const cx = 450, cy = 290;
H.text("Electric field of a point charge: E = k q / r^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Field points AWAY from + charge, TOWARD - charge; E weakens as 1/r^2 (k = 8.99e9)", 24, 52, { color: H.colors.sub, size: 13 });
const pos = q >= 0;
const cc = pos ? H.colors.warn : H.colors.accent;
// radial field arrows at several radii and angles
const radii = [60, 110, 165, 225];
const nAng = 12;
for (let i = 0; i < nAng; i++) {
  const a = (i / nAng) * H.TAU;
  const dx = Math.cos(a), dy = Math.sin(a);
  for (let j = 0; j < radii.length; j++) {
    const rp = radii[j];
    // arrow length scales like 1/r^2 (normalized), with a floor for visibility
    const len = 10 + 900 / (rp * 0.45);
    const L = Math.min(len, 34);
    const bx = cx + dx * rp, by = cy + dy * rp;
    const sgn = pos ? 1 : -1;
    H.arrow(bx, by, bx + dx * L * sgn, by + dy * L * sgn, { color: cc, width: 2 });
  }
}
// animated test point riding outward/inward showing E magnitude
const ra = 70 + 130 * (0.5 + 0.5 * Math.sin(t * 0.7));
const ang = 0.5 * t;
const tx = cx + Math.cos(ang) * ra, ty = cy + Math.sin(ang) * ra;
H.circle(tx, ty, 6, { fill: H.colors.good, stroke: H.colors.ink, width: 1 });
// physical r in meters: map 70px..200px to 0.1..2 m
const rPx = ra;
const rM = 0.1 + (rPx - 70) / 130 * 1.9;
const E = k * Math.abs(q) * 1e-6 / (rM * rM);
// central charge
H.circle(cx, cy, 20, { fill: cc, stroke: H.colors.ink, width: 2 });
H.text(pos ? "+" : "-", cx, cy, { color: "#0e1525", size: 22, align: "center", baseline: "middle", weight: 700 });
H.text("q = " + q.toFixed(1) + " uC", cx, cy - 32, { color: cc, size: 13, align: "center" });
H.line(cx, cy, tx, ty, { color: H.colors.sub, width: 1, dash: [3, 3] });
H.text("test charge: r = " + rM.toFixed(2) + " m", 24, 96, { color: H.colors.good, size: 13 });
H.text("E = " + E.toExponential(2) + " N/C", 24, 118, { color: H.colors.good, size: 14, weight: 700 });
